import math

def compute_cosine_sim(v1: list[float], v2: list[float]) -> float:
    dot = sum(a * b for a, b in zip(v1, v2))
    mag1 = math.sqrt(sum(a * a for a in v1))
    mag2 = math.sqrt(sum(b * b for b in v2))
    if mag1 * mag2 == 0:
        return 0.0
    return round(dot / (mag1 * mag2), 4)

import math

def compute_noisy_latent(x0: float, alpha_bar_t: float, eps: float) -> float:
    xt = math.sqrt(alpha_bar_t) * x0 + math.sqrt(1.0 - alpha_bar_t) * eps
    return round(xt, 4)

