def validate_agent_tool_call(tool_name: str, step: int, max_steps: int = 5) -> str:
    if step > max_steps:
        return 'BLOCKED_MAX_STEPS_EXCEEDED'
    if tool_name in REQUIRES_HUMAN_APPROVAL:
        return 'PENDING_HUMAN_APPROVAL'
    if tool_name in ALLOWED_READ_TOOLS:
        return 'ALLOWED_EXECUTE'
    return 'BLOCKED_UNAUTHORIZED_TOOL'

