def compute_p99_latency(latencies: list[float]) -> float:
    if not latencies:
        return 0.0
    sorted_l = sorted(latencies)
    idx = min(int(len(sorted_l) * 0.99), len(sorted_l) - 1)
    return sorted_l[idx]

