# Hàm cổng kiểm định nghiệm thu Dự án Capstone (Gate-Guarded Production Evaluator)
def evaluate_capstone_release(quality: float, groundedness: float, efficiency: float, p99_ms: float, safety_ok: bool) -> float:
    if not safety_ok or p99_ms > 1000.0:
        return 0.0  # Cổng chặn bắt buộc: Không cho phép xuất bản nếu vi phạm an toàn hoặc SLA
    weighted = (0.5 * quality) + (0.3 * groundedness) + (0.2 * efficiency)
    return round(weighted, 2)

